     const notificationChoices = [
       { id: "notify-email", value: "Email", label: "Email" },
       { id: "notify-sms", value: "SMS", label: "SMS" },
       { id: "notify-push", value: "Push Notifications", label: "Push Notifications" }
     ];

     function RadioOption({ id, value, label }) {
       return `
         <label class="option-card" for="${id}">
           <input id="${id}" type="radio" name="notificationPreference" value="${value}" required />
           <span class="option-text">${label}</span>
         </label>
       `;
