     function NotificationPreferenceField() {
       return `
         <div class="form-field">
           <p class="field-label">How do you prefer to receive notifications?</p>
           <fieldset class="options" aria-label="Notification preference">
             ${notificationChoices.map((choice) => RadioOption(choice)).join("")}
           </fieldset>
         </div>
       `;
